-- A view entity that reads another view entity: Trends.MeterYearVE over
-- Trends.MeterMonthVE. Mendix 10.24.24.119653, ConnectionBus_Retrieve at TRACE.
-- One GET, one statement, two nested derived tables - the inner one is the
-- month view, unchanged and unaware it is being read by anything.

SELECT  "Trends.MeterYearVE"."MeterCode", "Trends.MeterYearVE"."PeriodYear", "Trends.MeterYearVE"."TotalKwh", "Trends.MeterYearVE"."MonthsCovered", "Trends.MeterYearVE"."BusiestMonthKwh" FROM ( SELECT  "v"."MeterCode" AS "MeterCode", "v"."PeriodYear" AS "PeriodYear", SUM("v"."TotalKwh") AS "TotalKwh", COUNT("v"."MonthNo") AS "MonthsCovered", MAX("v"."TotalKwh") AS "BusiestMonthKwh" FROM ( SELECT  "m"."metercode" AS "MeterCode", "m"."region" AS "Region", (EXTRACT(YEAR FROM "r"."readat" AT TIME ZONE 'UTC' AT TIME ZONE 'UTC'))::integer AS "PeriodYear", (EXTRACT(MONTH FROM "r"."readat" AT TIME ZONE 'UTC' AT TIME ZONE 'UTC'))::integer AS "MonthNo", SUM("r"."kwh") AS "TotalKwh", COUNT("r"."id") AS "ReadingCount" FROM "trends$reading" "r" INNER JOIN "trends$meter" "m" ON "m"."id" = "r"."trends$reading_meter" GROUP BY "m"."metercode", "m"."region", (EXTRACT(YEAR FROM "r"."readat" AT TIME ZONE 'UTC' AT TIME ZONE 'UTC'))::integer, (EXTRACT(MONTH FROM "r"."readat" AT TIME ZONE 'UTC' AT TIME ZONE 'UTC'))::integer ) "v" GROUP BY "v"."MeterCode", "v"."PeriodYear" ) "Trends.MeterYearVE" ORDER BY "Trends.MeterYearVE"."MeterCode" ASC, "Trends.MeterYearVE"."PeriodYear" ASC LIMIT ?
